/**
 * personaImages.js (v2 - 압축 최적화)
 * 8 페르소나 캐릭터 카드 이미지 (JPEG base64)
 *
 * v2 변경: 384x512 → 240x320 다운스케일 + quality 75
 *   파일 크기: 477KB → 175KB (63% 감소)
 *   PDF 생성 시간 대폭 단축 (메인 스레드 블로킹 해소)
 *
 * 매칭 키 (4단계 폴백):
 *   1. personaInfo.key       (예: "MASTER_ARCHITECT")
 *   2. personaInfo.nameEn    (예: "Master Architect")
 *   3. nameEn 정규화 매칭     (대소문자/공백/하이픈 무시)
 *   4. personaInfo.name      (한글명 fallback)
 */

// ============================================================
// 페르소나 이미지 데이터 (KEY 기반)
// ============================================================

const PERSONA_IMAGE_DATA = {
  // MASTER_ARCHITECT — 완성형 설계자 (Master Architect)
  MASTER_ARCHITECT: "data:image/jpeg;base64,",

  // OPTIMISTIC_EXPLORER — 여유로운 탐험가 (Optimistic Explorer)
  OPTIMISTIC_EXPLORER: "data:image/jpeg;base64,",

  // ANXIOUS_ACHIEVER — 신중한 성취자 (Anxious Achiever)
  ANXIOUS_ACHIEVER: "data:image/jpeg;base64,",

  // SENSITIVE_CHALLENGER — 성장이 필요한 도전가 (Sensitive Challenger)
  SENSITIVE_CHALLENGER: "data:image/jpeg;base64,",

  // STRATEGIC_BUILDER — 전략적 레버리지 전문가 (Strategic Builder)
  STRATEGIC_BUILDER: "data:image/jpeg;base64,",

  // ACTIVE_RISK_TAKER — 열정적인 행동파 (Active Risk-Taker)
  ACTIVE_RISK_TAKER: "data:image/jpeg;base64,",

  // SAFE_HAVEN_KEEPER — 안정 중심 자산가 (Safe-Haven Keeper)
  SAFE_HAVEN_KEEPER: "data:image/jpeg;base64,",

  // DILIGENT_SAVER — 성실한 저축가 (Diligent Saver)
  DILIGENT_SAVER: "data:image/jpeg;base64,",

};

// ============================================================
// 영문명 → KEY 매핑
// ============================================================

const EN_TO_KEY = {
  "Master Architect": "MASTER_ARCHITECT",
  "Optimistic Explorer": "OPTIMISTIC_EXPLORER",
  "Anxious Achiever": "ANXIOUS_ACHIEVER",
  "Sensitive Challenger": "SENSITIVE_CHALLENGER",
  "Strategic Builder": "STRATEGIC_BUILDER",
  "Active Risk-Taker": "ACTIVE_RISK_TAKER",
  "Safe-Haven Keeper": "SAFE_HAVEN_KEEPER",
  "Diligent Saver": "DILIGENT_SAVER",
};

// ============================================================
// 한글명 → KEY 매핑
// ============================================================

const KR_TO_KEY = {
  "완성형 설계자": "MASTER_ARCHITECT",
  "여유로운 탐험가": "OPTIMISTIC_EXPLORER",
  "신중한 성취자": "ANXIOUS_ACHIEVER",
  "성장이 필요한 도전가": "SENSITIVE_CHALLENGER",
  "전략적 레버리지 전문가": "STRATEGIC_BUILDER",
  "열정적인 행동파": "ACTIVE_RISK_TAKER",
  "안정 중심 자산가": "SAFE_HAVEN_KEEPER",
  "성실한 저축가": "DILIGENT_SAVER",
  "열정적 행동파": "ACTIVE_RISK_TAKER",  // alias
};

// ============================================================
// 정규화 유틸
// ============================================================

function normalizeKey(str) {
  if (!str || typeof str !== "string") return "";
  return str.toLowerCase().replace(/[\s\-_]+/g, "");
}

const NORMALIZED_EN_TO_KEY = {};
Object.keys(EN_TO_KEY).forEach((en) => {
  NORMALIZED_EN_TO_KEY[normalizeKey(en)] = EN_TO_KEY[en];
});

// ============================================================
// 메인 헬퍼
// ============================================================

export function getPersonaCardImage(personaInfo) {
  if (!personaInfo) return null;
  const { key, name, nameEn } = personaInfo;
  if (key && PERSONA_IMAGE_DATA[key]) return PERSONA_IMAGE_DATA[key];
  if (nameEn && EN_TO_KEY[nameEn]) return PERSONA_IMAGE_DATA[EN_TO_KEY[nameEn]];
  if (nameEn) {
    const matchedKey = NORMALIZED_EN_TO_KEY[normalizeKey(nameEn)];
    if (matchedKey) return PERSONA_IMAGE_DATA[matchedKey];
  }
  if (name && KR_TO_KEY[name]) return PERSONA_IMAGE_DATA[KR_TO_KEY[name]];
  return null;
}

export const PERSONA_IMAGE_KEYS = Object.keys(PERSONA_IMAGE_DATA);
